} from "../../parser/index.js";
import { commitIfShadow } from "../../parser/shadow.js";
import { normalizeRefInput } from "../../schema/index.js";
import type { Task, TaskInput } from "../../schema/index.js";
import { alignmentCheck, errors } from "../../strings/index.js";
import {
  formatCommitGuidance,
  printCommitGuidance,
} from "../../utils/commit.js";
import { executeBatchOperation, formatBatchOutput } from "../batch.js";
import { EXIT_CODES } from "../exit-codes.js";
import { parseTagsArray } from "../parse-utils.js";
import {
  annotateNotesWithSuperseded,
  error,
  formatTaskDetails,
  info,
  isJsonMode,
  output,
  success,
  warn,
} from "../output.js";
import {
  parsePriority,
  validateEnumOption,
  validateSpecRef,
} from "../validators.js";
import { addListOptions, listTasksAction } from "./tasks.js";
import { findClosestCommand } from "../suggest.js";
import { checkBudget, incrementBudget, isEndLoopRequested } from "../../sessions/store.js";
import { PidFileManager } from "../pid-utils.js";

/**
 * Post a task state change event to the daemon dispatch engine.
 * Fails silently — dispatch requires a running daemon; if absent, this is a no-op.
 * AC: @daemon-agent-dispatch ac-2, ac-7
 */
async function postDispatchEvent(opts: {
  taskId: string;
  taskRef: string;
  fromStatus: string;
  toStatus: string;
  projectPath?: string;
}): Promise<void> {
  const pidManager = new PidFileManager();
  if (!pidManager.isDaemonRunning()) return;

  let port: number;
  try {
    port = pidManager.readPort();
  } catch {
    return; // Daemon running but port unreadable — silent fail
  }

  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (opts.projectPath) {
    headers['X-Kspec-Dir'] = opts.projectPath;
  }

  try {
    await fetch(`http://localhost:${port}/api/agent/events`, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        task_id: opts.taskId,
        task_ref: opts.taskRef,
        from_status: opts.fromStatus,
        to_status: opts.toStatus,
        timestamp: Date.now(),
      }),
      signal: AbortSignal.timeout(1000), // 1s timeout — fire-and-forget
    });
  } catch {
    // Silent fail — daemon unreachable or dispatch engine not running
  }
}

/**
 * Find a task by reference with detailed error reporting.
 * Returns the task or exits with appropriate error.
 */
function resolveTaskRef(
  ref: string,
  tasks: LoadedTask[],
  index: ReferenceIndex,
): LoadedTask {
  const result = index.resolve(ref);

  if (!result.ok) {
    switch (result.error) {
      case "not_found":
        error(errors.reference.taskNotFound(ref));
        break;
      case "ambiguous":
        error(errors.reference.ambiguous(ref));
        for (const candidate of result.candidates) {
          const task = tasks.find((t) => t._ulid === candidate);
          const slug = task?.slugs[0] || "";
          console.error(
            `  - ${index.shortUlid(candidate)} ${slug ? `(${slug})` : ""}`,
          );
        }
        break;
      case "duplicate_slug":
        error(errors.reference.slugMapsToMultiple(ref));
        for (const candidate of result.candidates) {
          console.error(`  - ${index.shortUlid(candidate)}`);
        }
        break;
    }
    // AC: @cli-exit-codes consistent-usage - NOT_FOUND for missing resources
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  // Check if it's actually a task
  const task = tasks.find((t) => t._ulid === result.ulid);
  if (!task) {
    error(errors.reference.notTask(ref));
    // AC: @cli-exit-codes consistent-usage - NOT_FOUND for missing resources
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  return task;
}

/**
 * Batch-compatible resolver that returns null instead of calling process.exit().
 * Used by executeBatchOperation to handle errors without terminating the process.
 * AC: @multi-ref-batch ac-4, ac-8 - Partial failure handling and ref resolution

